const fs = require('fs');
const html = fs.readFileSync('index.html','utf8');
// Quick validation: check slide count, required elements
const slides = html.split('<section class=\"slide').length - 1;
const canvasCards = html.split('class=\"canvas-card\"').length - 1;
const chromeMins = html.split('class=\"chrome-min\"').length - 1;
const asciiBgs = html.split('class=\"ascii-bg\"').length - 1;
const dataAnimates = (html.match(/data-animate=/g) || []).length;
const recipes = html.match(/data-animate=\"([^\"]+)\"/g).map(m => m.match(/\"([^\"]+)\"/)[1]);

// Check if title is replaced
const hasPlaceholder = html.includes('[必填]');
console.log('=== Validation ===');
console.log('Slides:', slides);
console.log('canvas-card:', canvasCards);
console.log('chrome-min:', chromeMins);
console.log('ascii-bg:', asciiBgs);
console.log('data-animate occurrences:', dataAnimates);
console.log('Recipes used:', [...new Set(recipes)]);
console.log('Has placeholder [必填]:', hasPlaceholder ? 'YES ⚠️' : 'NO ✅');
console.log('Deck divs opened:', (html.match(/<div[^>]*id=\"deck\"/g) || []).length);
console.log('Deck divs closed:', (html.match(/<\/div>\n*<div id=\"nav\"/) ? 'OK' : 'CHECK'));
"

